package net.battlespades.session;
import java.util.*;
import java.util.function.Consumer;
import net.battlespades.match.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.protocol.DropPickup.Position;
import net.battlespades.rules.GameRules;
import net.battlespades.world.MutableWorld.Cell;
import org.tomlj.TomlTable;

/** Mining discovery, serial-preserving carry/drop, capacity rotation and source objective economy. */
public final class HostedDiamondRuntime extends HostedCarryRuntime {
    private static final class Dropoff {final ObjectiveZone zone;final int team,capacity;int remaining;boolean active;Dropoff(ObjectiveZone z,int t,int c){zone=z;team=t;capacity=remaining=c;}}
    private static final class Diamond {int id,serial,lastTeam=1;Vector at;double born,expires,pickup;}
    private static final class History {final PlayerLife finder;final Set<Integer> teams=new HashSet<>();History(PlayerLife p){finder=p;}}
    public record Ground(int id,int serial,Vector position,double expires,double pickupAfter,int lastTeam){}
    public record Base(ObjectiveZone zone,int team,int remaining,boolean active){}
    private final int maxBases,maxDiamonds,guarantee;private final double lifetime;private final boolean loose;private final SourceRandom random;
    private final List<Dropoff> bases=new ArrayList<>(),activeBases=new ArrayList<>();private final Map<Integer,Diamond> ground=new LinkedHashMap<>();private final Map<PlayerLife,Integer> carriers=new LinkedHashMap<>();private final Map<Integer,History> history=new HashMap<>();private final EscortTracker escorts=new EscortTracker(15,10);private final Set<PlayerLife> helped=Collections.newSetFromMap(new WeakHashMap<>());
    private int serial=1,mined;private double nextDiscovery,nextScore;
    public HostedDiamondRuntime(StandardMatchDomain m,ApplicationHost h,CarryMode mode,SpawnGeometry geometry,TomlTable raw,GameRules rules,SourceRandom random){super(m,h,mode,geometry,raw);this.random=random;maxBases=(int)Math.max(1,Math.min(5,CtfMode.Settings.number(raw,"modes.dia.max_active_bases",rules.number("RULE_DIAMOND_MAX_ACTIVE_BASES"))));maxDiamonds=(int)Math.max(1,Math.min(5,CtfMode.Settings.number(raw,"modes.dia.max_active_diamonds",rules.number("RULE_MAX_ACTIVE_DIAMONDS"))));lifetime=Math.max(1,CtfMode.Settings.number(raw,"modes.dia.diamond_lifetime",rules.number("RULE_DIAMOND_LIFETIME")));guarantee=(int)Math.max(0,CtfMode.Settings.number(raw,"modes.dia.discovery_guarantee_blocks",300));loose=CtfMode.Settings.flag(raw,"modes.dia.loose_cash_in",true);}
    public List<Ground> ground(){owned();return ground.values().stream().map(d->new Ground(d.id,d.serial,d.at,d.expires,d.pickup,d.lastTeam)).toList();}
    public List<Base> bases(){owned();return bases.stream().map(b->new Base(b.zone,b.team,b.remaining,b.active)).toList();}
    public boolean carrying(PlayerLife p){owned();return carriers.containsKey(p);}
    public void start(){owned();for(var b:activeBases)broadcast(b.zone.clear());bases.clear();activeBases.clear();mined=0;escorts.reset();var metadata=match.metadata();int shift=match.world().sourceZShift();for(int i=0;i<Math.min(10,metadata.diamondBases().size());i++){var z=metadata.diamondBases().get(i);int capacity=metadata.diamondCapacities().size()>i?metadata.diamondCapacities().get(i).max(java.math.BigInteger.ONE).min(java.math.BigInteger.valueOf(Integer.MAX_VALUE)).intValue():1;bases.add(new Dropoff(ObjectiveZone.from(i,z,shift),z.team(),capacity));}
        if(bases.isEmpty()){var a=anchor(2);var b=anchor(3);for(double f:new double[]{.25,.5,.75})bases.add(new Dropoff(ObjectiveZone.around(bases.size(),ground(a.x()+(b.x()-a.x())*f,a.y()+(b.y()-a.y())*f),12,8,8),1,1));}
        for(int i=0;i<Math.min(maxBases,bases.size());i++){var b=bases.get(i);b.active=true;b.remaining=b.capacity;activeBases.add(b);broadcast(packet(b));}nextDiscovery=match.wall();nextScore=match.wall()+5;for(var p:match.lives().players())tell(p,"DIAMOND_START",List.of());
    }
    private GamePacket packet(Dropoff b){return b.zone.packet(b.team==1?0xffffff:team(b.team).color(),4);}
    private Diamond spawn(Vector at,PlayerLife finder,double delay){var d=new Diamond();d.serial=serial++;d.at=at;d.born=match.wall();d.expires=d.born+lifetime;d.pickup=d.born+delay;d.id=entity(15,at,"diamond",lifetime);ground.put(d.id,d);if(finder!=null){history.put(d.serial,new History(finder));award(finder,10,39);announce("DIAMOND_UNCOVERED",List.of(finder.name()),false);sound(4,null);}return d;}
    private void remove(Diamond d){ground.remove(d.id);remove(d.id,"diamond");}
    public void mined(PlayerLife p,List<Cell> cells,boolean mining){owned();if(!open()||!mining||!active(p)||cells.isEmpty())return;mined+=cells.size();int count=ground.size()+carriers.size();if(count>=maxDiamonds||match.wall()<nextDiscovery)return;double chance=.01+(.002-.01)*count/maxDiamonds,event=1-Math.pow(1-chance,cells.size());boolean due=guarantee>0&&count==0&&mined>=guarantee;if(!due&&random.random()>event)return;var c=cells.get(random.below(cells.size()));spawn(new Vector(c.x()+.5,c.y()+.5,c.z()+.5),p,0);mined=0;nextDiscovery=match.wall()+15;}
    private Dropoff cashable(Vector at,int team){return activeBases.stream().filter(b->b.remaining>0&&(b.team==1||b.team==team)&&b.zone.contains(at)).findFirst().orElse(null);}
    private void pickup(PlayerLife p,Diamond d){if(!ObjectiveCarry.pickup(p,15,true,d.serial,this::broadcast))return;var hist=history.computeIfAbsent(d.serial,k->new History(null));match.carryObservation(new Observation("diamond_picked_up",p,hist.finder,d.serial,d.lastTeam!=1,hist.teams.isEmpty()?match.wall()-d.born:null,d.at,d.lastTeam));hist.teams.add(p.team());carriers.put(p,d.serial);guard.endProtection(p);remove(d);teamMessage(p.team(),"DIAMOND_PICKEDUP_YOURTEAM",List.of(p.name()),null,false);teamMessage(5-p.team(),"DIAMOND_PICKEDUP_OPPOSITION",List.of(p.name()),null,false);}
    private void afterScore(int team,Dropoff b){b.remaining--;relative(team,6);checkScore(team);if(!open())return;if(this.team(team).score>=Math.max(1,mode.settings().target()-3))match.openMapVote();if(b.remaining<=0){b.active=false;activeBases.remove(b);broadcast(b.zone.clear());var replacement=bases.stream().filter(v->!v.active&&v!=b).findFirst().orElse(b);replacement.active=true;replacement.remaining=replacement.capacity;activeBases.add(replacement);broadcast(packet(replacement));announce("DIAMOND_BASE",List.of(),false);}}
    private void cash(PlayerLife p,Dropoff b){if(nativeDrop(p,position(p.position()),new Position(0,0,0),false)==null)return;int id=carriers.remove(p);escorts.forget(p);var hist=history.remove(id);if(hist!=null){if(hist.teams.stream().anyMatch(t->t!=p.team()))match.profiles().add(match.binding().row(p),47,1,0);if(hist.finder==p)match.profiles().add(match.binding().row(p),48,1,0);}observation("diamond_cashed_in",p,null,id,hist!=null&&hist.finder==p,null,p.position());award(p,100,38);teamScore(p.team(),1,38);tell(p,"DIAMOND_CASHED_IN_YOURSELF",List.of());teamMessage(p.team(),"DIAMOND_CASHED_IN_YOURTEAM",List.of(p.name()),p,false);teamMessage(5-p.team(),"DIAMOND_CASHED_IN_OPPOSITION",List.of(p.name()),null,false);afterScore(p.team(),b);}
    private boolean cashLoose(Diamond d){if(!loose||!open()||d.lastTeam==1||!ground.containsKey(d.id))return false;var b=cashable(d.at,d.lastTeam);if(b==null)b=cashable(new Vector(d.at.x(),d.at.y(),d.at.z()-2.25),d.lastTeam);if(b==null)return false;remove(d);history.remove(d.serial);teamScore(d.lastTeam,1,38);teamMessage(d.lastTeam,"DIAMOND_CASHED_IN_LOOSE_YOURTEAM",List.of(),null,false);teamMessage(5-d.lastTeam,"DIAMOND_CASHED_IN_LOOSE_OPPOSITION",List.of(),null,false);afterScore(d.lastTeam,b);return true;}
    public void tick(){owned();if(!open())return;double now=match.wall();for(var d:List.copyOf(ground.values())){var e=match.entities().registry().get(d.id);if(e!=null)e.fuse=Math.max(0,d.expires-now);if(now>=d.expires){remove(d);history.remove(d.serial);sound(5,d.at);}else if(d.lastTeam!=1){cashLoose(d);if(!open())return;}}
        for(var p:match.lives().players()){if(!active(p))continue;if(!carrying(p)){var d=ground.values().stream().filter(v->ObjectiveScores.within(p.position(),v.at,3)&&guard.pickupVisible(p,v.at,false,.25)).min(Comparator.comparingInt(v->v.id)).orElse(null);if(d!=null&&now>=d.pickup)pickup(p,d);}if(carrying(p)){var b=cashable(p.position(),p.team());if(b!=null){cash(p,b);if(!open())return;}}}
        if(now>=nextScore){long periods=(long)Math.floor((now-nextScore)/5)+1;nextScore+=periods*5;for(var p:List.copyOf(carriers.keySet()))if(active(p)){award(p,periods*50,40);for(var escort:escorts.escorts(p,match.lives().players()))award(escort,periods*10,41);}}
    }
    public boolean drop(PlayerLife p,Position at,Position speed,boolean forced,Integer oldTeam){owned();var id=carriers.get(p);if(id==null)return false;var dropped=nativeDrop(p,at,speed,forced);if(dropped==null&&!forced)return true;carriers.remove(p);escorts.forget(p);if(!open()){history.remove(id);return true;}Vector settled=surface(dropped==null?p.position().x():dropped.position().x(),dropped==null?p.position().y():dropped.position().y());sound(23,settled);var d=spawn(settled,null,2.5);d.serial=id;d.lastTeam=oldTeam==null?p.team():oldTeam;cashLoose(d);return true;}
    public void death(Scoreboard.Player v,Scoreboard.Player k,int type){owned();if(open()&&ObjectiveScores.eligible(k,v,type)){var kc=carriers.keySet().stream().filter(p->p.team()==k.team()).map(p->match.binding().row(p)).toList();var vc=carriers.keySet().stream().filter(p->p.team()==v.team()).map(p->match.binding().row(p)).toList();String event=ObjectiveScores.classify(k,v,carrying(v.life),kc,ground.values().stream().map(d->d.at).toList(),activeBases.stream().filter(b->b.remaining>0&&(b.team==1||b.team==k.team())).map(b->b.zone.center()).toList(),10,20);scores.killEvent(k,event,Map.of("intercept",50L,"carrier_defend",100L,"defend",50L,"assault",50L,"assault_enemy",50L,"distract",100L),Map.of("intercept",46,"carrier_defend",43,"defend",44,"assault",45,"assault_enemy",45,"distract",42),Optional.empty());if(ObjectiveScores.distraction(v,k,type,vc,15))award(v.life,100,42);}retire(v.life,null);}
    public void spawned(PlayerLife p){if(host.inGame(p.id())&&helped.add(p))personal(p,new HelpMessage(0,List.of("DIAMOND_TUTORIAL","DIA_INFOGRAPHIC_TEXT1","DIA_INFOGRAPHIC_TEXT2","DIA_INFOGRAPHIC_TEXT3")));}
    public void reveal(Consumer<GamePacket> send){owned();for(var b:activeBases)send.accept(packet(b));}
    public void startCue(PlayerLife p,Consumer<GamePacket> send){send.accept(Announcements.localised("DIAMOND_START",List.of(),false,false));if(helped.add(p))send.accept(new HelpMessage(0,List.of("DIAMOND_TUTORIAL","DIA_INFOGRAPHIC_TEXT1","DIA_INFOGRAPHIC_TEXT2","DIA_INFOGRAPHIC_TEXT3")));}
    public void clear(){owned();for(var p:List.copyOf(carriers.keySet())){if(current(p))nativeDrop(p,position(p.position()),new Position(0,0,0),true);else ObjectiveCarry.clear(p);}for(var d:List.copyOf(ground.values()))remove(d);for(var b:activeBases){broadcast(b.zone.clear());b.active=false;}activeBases.clear();carriers.clear();history.clear();escorts.reset();}
}
